-- =============================================================================
-- !!! SOMENTE BANCO LOCAL (desbloqueia_local) — NUNCA EM PRODUÇÃO OU HOMOLOGAÇÃO !!!
-- Este arquivo APAGA linhas com ids 9000-9999 em tabelas reais (usuarios,
-- inscricoes, pedidos, certificados, conteudo_* …) e CRIA um usuário com senha
-- conhecida (Local@12345). Ele aborta sozinho se o banco atual não for
-- desbloqueia_local (guarda logo abaixo de SET NAMES).
-- =============================================================================
-- Fixture LOCAL da área do aluno (aula, quiz, atividade) do tema caderno.
--
--   *** NÃO aplicar em produção. ***  Só para o banco de desenvolvimento local
--   (docker/local). Idempotente: apaga e recria tudo pelos ids fixos 9001-9999
--   (e códigos marcados CADFIX-/CAD-ALU-) e nunca toca em outras linhas. Pode
--   rodar de novo para "resetar" os estados (cronômetro da prova, prazos,
--   respostas, conclusões feitas durante os testes).
--
--   docker exec -i desbloqueia-db-1 mysql -uroot desbloqueia_local < tests/Fixtures/tema_caderno_aluno.sql
--
-- LOGIN DE TESTE (local, http://127.0.0.1:8010/v2/login)
--   e-mail: aluno.caderno@teste.local     senha: Local@12345
--   (CPF 987.654.321-00; também entra por CPF)
--
-- O QUE CRIA (aluna 9001)
--   Cursos/inscrições (inscricao_id = turma_id = curso_id, tudo 9001..9003):
--     9001  Curso de estudo do caderno (fixture)   em andamento, com módulos e todos os tipos
--     9002  Oficina concluída (fixture)             100% + certificado emitido (CADFIX-2026-0001)
--     9003  Curso em preparação (fixture)           matriculada, SEM módulos publicados
--   Pedidos (aba Pedidos): 9008 aprovado (curso 9003), 9007 rascunho sem item
--   ("Pedido sem curso identificado", cancelável), 9006 aguardando pagamento com
--   2 cursos, 9005 cancelado, 9004 comprovante enviado (cancelável, sem
--   "retomar"), 9003 aguardando pagamento 1 curso (retomar + cancelar), 9002 e
--   9001 aprovados (os dois cursos com acesso).
--
-- ROTEIRO DE URLs (prefixo http://127.0.0.1:8010; CTX = inscricao_id=9001&curso_id=9001&turma_id=9001)
--   Área do aluno
--     /v2/aluno                          aba cursos (3 cursos: andamento, concluído+certificado, em preparação)
--     /v2/aluno?aba=pedidos              8 pedidos (1 e vários cursos, sem curso, retomar/cancelar)
--     /v2/aluno?aba=certificados         1 certificado
--     /v2/aluno?aba=perfil               perfil (CPF/telefone mascarados)
--     /v2/aluno?aba=xyz                  aba inválida -> cursos
--     /v2/minha-conta                    ficha (estado SP, cidade São Paulo)
--   Aula (/v2/aula?CTX&modulo_id=M&conteudo_id=ID)
--     /v2/aula                           sem inscrição: "Selecione um curso" (200)
--     /v2/aula?inscricao_id=9001&curso_id=9002&turma_id=9001   404 "Conteúdo indisponível" (curso não corresponde;
--                                        inscricao_id inexistente NÃO dá 404: o app cai na primeira inscrição da aluna)
--     /v2/aula?inscricao_id=9003&curso_id=9003&turma_id=9003    curso sem módulos ("Conteúdo a caminho")
--     /v2/aula?CTX                       visão geral (4 módulos; módulo 4 vazio)
--     conteudo_id=9001 etiqueta (só na árvore)         conteudo_id=9002 texto rico, já concluído (Desmarcar)
--     conteudo_id=9003 HTML em iframe (sandbox)        conteudo_id=9004 vídeo YouTube resolvido
--     conteudo_id=9005 vídeo sem embed ("Assistir vídeo")   conteudo_id=9006 vídeo sem link
--     conteudo_id=9007 vídeo incorporado (iframe)      conteudo_id=9008 arquivo (Baixar material; o arquivo não existe em disco)
--     conteudo_id=9009 link                            conteudo_id=9010 texto vazio ("Conteúdo sem texto disponível")
--     conteudo_id=9019 item em rascunho -> item inacessível
--     conteudo_id=9011 (quiz) e 9021 (atividade)       cartões que levam a /v2/quiz e /v2/atividade
--   Quiz (/v2/quiz?CTX&modulo_id=9002&conteudo_id=ID)
--     9011  curto, 3 perguntas, sem tentativas   -> "antes de começar"; POST iniciar -> andamento (uma pergunta por vez)
--     9014  curto, 1 tentativa corrigida (2/3, aprovado, gabarito + explicações)  -> &tentativa_id=9014 mostra o resultado
--     9015  curto, resultado/gabarito/comentários desligados -> &tentativa_id=9015 "Quiz enviado com sucesso"
--     9016  curto EM ANDAMENTO (1 pergunta respondida, sem prazo) -> abre direto o formulário
--     9018  curto EM ANDAMENTO com UMA ÚNICA pergunta (sem navegação; a pergunta aparece na hora)
--     9012  PROVA (duração 60 min, 2 tentativas, blocos: objetivas + discursiva) -> "antes de começar" com estrutura
--     9017  PROVA: tentativa 1 enviada (&tentativa_id=9171 mostra o resultado) + tentativa 2 EM ANDAMENTO com
--           cronômetro de ~3 h (modo prova: discursiva, blocos, marcar para revisão); expira 3 h após aplicar a fixture.
--           Para testar o visual "tempo acabando": UPDATE conteudo_quiz_tentativas SET expira_em = DATE_ADD(NOW(), INTERVAL 4 MINUTE) WHERE id = 9172;
--   Atividade (/v2/atividade?CTX&modulo_id=9003&conteudo_id=ID)
--     9021 sem entrega, prazo aberto (pode enviar)           9022 em correção (enviada; não pode reenviar)
--     9023 devolvida (reenvio liberado)                      9024 corrigida: nota 8,50 + devolutiva + 2 imagens
--     9025 aprovada (nota 10)                                9026 reprovada (pode enviar de novo)
--     9027 cancelada                                         9028 sem entrega e prazo vencido (não pode enviar)
--     /v2/atividade?CTX&modulo_id=9002&conteudo_id=9011      tipo quiz -> estado "externo"
--     /v2/atividade?CTX&conteudo_id=9019                     item não publicado -> 404
--
-- LIMITES: o arquivo do item 9008 e as imagens da atividade 9024 não existem em
-- disco (os registros apontam para caminhos fictícios): as páginas renderizam,
-- mas o download/imagem devolve erro. O ambiente local não tem professor/admin
-- nesta fixture; correções são simuladas pelas linhas prontas acima.
-- =============================================================================

SET NAMES utf8mb4;

-- Guarda: fora de desbloqueia_local o SELECT abaixo falha ("Subquery returns more
-- than 1 row") e o cliente mysql para aqui, antes de qualquer DELETE.
SELECT IF(DATABASE() = 'desbloqueia_local', 'fixture: banco local ok', (SELECT 'ABORTADO: banco errado' UNION SELECT 'use desbloqueia_local')) AS guarda_fixture;
SET @OLD_FK = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;

